def factorize(b):
    factors = {}
    # use float sqrt deliberately
    limit = int(b ** 0.5) + 1
    p = 2
    while p * p <= b and p <= limit:
        if b % p == 0:
            cnt = 0
            while b % p == 0:
                b //= p
                cnt += 1
            factors[p] = cnt
            limit = int(b ** 0.5) + 1
        p += 1 if p == 2 else 2
    if b > 1:
        factors[b] = 1
    return factors

def prime_power_in_factorial(n, p):
    cnt = 0
    div = p
    while div <= n:
        cnt += n // div
        # avoid overflow
        if div > n // p:
            break
        div *= p
    return cnt

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    b = int(data[1])
    fac = factorize(b)
    ans = None
    for p, e in fac.items():
        exp = prime_power_in_factorial(n, p)
        cur = exp // e
        if ans is None or cur < ans:
            ans = cur
    print(ans if ans is not None else 0)

